async function broadcast(message){for(const client of await self.clients.matchAll({includeUncontrolled:true}))client.postMessage(message);}
async function verify(){const cache=await caches.open(CACHE),keys=new Set((await cache.keys()).map(r=>r.url));const missing=ASSETS.filter(a=>!keys.has(absolute(a.path)));return {type:'CACHE_STATUS',build:BUILD,ready:missing.length===0,count:ASSETS.length-missing.length,total:ASSETS.length};}
let preparing;
function prepare(){if(preparing)return preparing;preparing=(async()=>{const cache=await caches.open(CACHE);let done=0,cursor=0;
async function worker(){while(cursor<ASSETS.length){const asset=ASSETS[cursor++],url=absolute(asset.path);if(!(await cache.match(url))){const response=await fetch(new Request(url,{cache:'reload',credentials:'same-origin'}));if(!response.ok||response.redirected)throw new Error('無法下載 '+asset.path+'（HTTP '+response.status+'）');const raw=await response.clone().arrayBuffer();const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',raw))).map(n=>n.toString(16).padStart(2,'0')).join('');if(digest!==asset.sha256)throw new Error('檔案版本不一致：'+asset.path);await cache.put(url,response);}done++;if(done%8===0||done===ASSETS.length)await broadcast({type:'CACHE_PROGRESS',build:BUILD,count:done,total:ASSETS.length});}}
await Promise.all(Array.from({length:4},worker));const status=await verify();if(!status.ready)throw new Error('快取未完整');await broadcast(status);return status;
})().catch(async error=>{await broadcast({type:'CACHE_ERROR',message:error.message});throw error;}).finally(()=>{preparing=null;});return preparing;}
self.addEventListener('install',event=>event.waitUntil(prepare()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{await self.clients.claim();await broadcast(await verify());})()));
self.addEventListener('message',event=>{if(event.data?.type==='STATUS')event.waitUntil(verify().then(status=>event.ports[0]?.postMessage(status)));if(event.data?.type==='PREPARE')event.waitUntil(prepare().catch(()=>{}));if(event.data?.type==='ACTIVATE')self.skipWaiting();});
self.addEventListener('fetch',event=>{const u=new URL(event.request.url);if(event.request.method!=='GET'||u.origin!==BASE.origin||!u.pathname.startsWith(BASE.pathname))return;
event.respondWith((async()=>{const cache=await caches.open(CACHE);u.search='';u.hash='';if(u.pathname===BASE.pathname)u.pathname+='index.html';const cached=await cache.match(u.href);if(cached)return cached;return new Response('離線檔案尚未備妥。請連網後返回首頁，重新準備離線資料。',{status:503,headers:{'Content-Type':'text/plain; charset=utf-8'}});})());});
